function validate([items, ruleKey, ruleValue]) {
  const ok = s => typeof s === 'string' && /^[a-z]{1,10}$/.test(s);
  if (!Array.isArray(items) || items.length < 1 || items.length > 10000) return 'items needs 1 to 10^4 entries.';
  if (items.some(item => !Array.isArray(item) || item.length !== 3)) return 'Each item is [type, color, name].';
  if (items.some(item => !item.every(ok))) return 'Item strings are 1 to 10 lowercase letters.';
  if (!['type', 'color', 'name'].includes(ruleKey)) return 'ruleKey is "type", "color" or "name".';
  if (!ok(ruleValue)) return 'ruleValue is 1 to 10 lowercase letters.';
  return null;
}

