function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const word = () => {
    const length = 1 + Math.floor(rand() * 10);
    let text = '';
    for (let i = 0; i < length; i++) text += String.fromCharCode(97 + Math.floor(rand() * 26));
    return text;
  };
  // A small shared vocabulary makes matches (and cross-field look-alikes) common.
  const vocab = size === 'large'
    ? Array.from({ length: 12 }, word)
    : ['phone', 'pc', 'tv', 'blue', 'red', 'silver', 'pixel', 'a', 'b'];
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const items = Array.from({ length: n }, () => [pick(vocab), pick(vocab), pick(vocab)]);
  const ruleKey = pick(['type', 'color', 'name']);
  const ruleValue = rand() < 0.85 ? pick(vocab) : word();
  return [items, ruleKey, ruleValue];
}
